class Config(object):
    """Handle the retrieval of configuration options.

    ``repository`` is the source of configuration values (e.g. a
    ``RepositoryEnv`` or ``RepositoryDict`` instance).  ``environ`` is the
    mapping consulted for environment variable overrides; it defaults to
    ``os.environ``.
    """

    def __init__(self, repository, environ=None):
        self.repository = repository
        self.environ = os.environ if environ is None else environ

    def _cast_boolean(self, value):
        """Convert config values to boolean as ConfigParser does."""
        value = str(value)
        return bool(value) if value == '' else bool(strtobool(value))


